export interface SlideElement {
  id: string;
  type: 'text' | 'shape' | 'image';
  content: string;
  x: number;
  y: number;
  w: number;
  h: number;
  fontSize?: number;
  fontFamily?: string;
  fontWeight?: string;
  fontStyle?: string;
  textDecoration?: string;
  textAlign?: 'left' | 'center' | 'right';
  lineHeight?: number;
  color?: string;
  shape?: 'rect' | 'circle' | 'rounded' | 'triangle' | 'diamond' | 'star' | 'arrow' | 'hexagon';
  fill?: string;
  stroke?: string;
  strokeWidth?: number;
  opacity?: number;
  rotation?: number;
  borderRadius?: number;
  shadow?: boolean;
  zIndex?: number;
  locked?: boolean;
  hidden?: boolean;
  imageUrl?: string;
  imageFit?: 'cover' | 'contain' | 'fill';
  gradient?: string;
  blur?: number;
  letterSpacing?: number;
}

export interface Slide {
  id: string;
  elements: SlideElement[];
  bg: string;
  bgGradient?: string;
  bgImage?: string;
  notes: string;
  transition?: 'none' | 'fade' | 'slide' | 'zoom' | 'flip' | 'blur';
}

export interface SlideTheme {
  id: string;
  name: string;
  bg: string;
  bgGradient?: string;
  titleColor: string;
  textColor: string;
  accentColor: string;
  fontFamily: string;
  category?: string;
}

